import {CheckCircleFillIcon, CircleIcon} from '@primer/octicons-react'
import {Heading, LinkButton, Stack} from '@primer/react'
import type React from 'react'
import {useState} from 'react'

import styles from './Stepper.module.css'

export type AnalyticsEntry = {category: string; action: string}

/**
 * Base step data type used by all steps and buttons within a step.
 */
export type BaseStepData = {
  /**
   * Optional label text for a primary CTA button rendered for the step. Only
   * use one of customContent, customCta, multipleCtaButtons, or ctaLabel.
   */
  ctaLabel?: string
  /**
   * Optional URL the primary CTA will navigate to. When provided, navigation
   * happens after the step completion handler is invoked.
   */
  href?: string
  /**
   * Optional URL for a form action the step should perform.  Only use one of
   * href or formAction.
   */
  formAction?: string
  /**
   * Whether the step is currently complete. This is typically controlled by
   * the parent component (via state) and causes the step to render as
   * completed (check icon).
   */
  isComplete?: boolean
  /**
   * If true, the step should be treated as automatically completed by the
   * UI (for example when backend conditions are satisfied).
   */
  autoComplete?: boolean
  /**
   * Optional analytics metadata emitted when the step is interacted with.
   * Minimal shape: { category: string, action: string }
   */
  analytics?: AnalyticsEntry
}

/**
 * Full step data type used by parent steps.
 */
export type StepData = BaseStepData & {
  /** The visible title for the step. */
  title: string
  /**
   * Optional description for the step. Can be a plain string, a React node,
   * or a render function which receives { onComplete } and should return a
   * React node. The render function can call onComplete() to mark the step
   * completed (this will call the parent `onStepActionClick` callback).
   */
  description?: string | React.ReactNode | ((props: {onComplete: () => void}) => React.ReactNode)
  /**
   * Optional custom content node to render in the step panel instead of the
   * default description + CTA rendering.
   */
  customContent?: React.ReactNode
  /**
   * Optional custom CTA render-prop. Receives an object with
   * { onComplete, index, isActive } and should return a React node. Use
   * onComplete() to signal the step is finished.
   */
  customCta?: (props: {onComplete: () => void; index: number; isActive: boolean}) => React.ReactNode
  /**
   * If present, renders a horizontal stack of buttons instead of a single
   * CTA button. Each button should handle calling onComplete() when clicked.
   */
  multipleCtaButtons?: BaseStepData[]
}

export interface StepperProps {
  /**
   * Array of step metadata objects describing each step to render.
   */
  steps: StepData[]
  /**
   * If provided, the component is controlled and will use this value as the
   * currently active step index. When omitted the component manages active
   * index internally (uncontrolled mode).
   */
  activeStepIndex?: number
  /**
   * Callback invoked when the active step changes (user clicks a step
   * header). Receives the new active index.
   */
  onStepChange: (newIndex: number) => void
  /**
   * Callback invoked when a step CTA is clicked.  Receives the step index
   * and, if applicable, the index of the button within multipleCtaButtons
   * or a boolean `isCustom` if onComplete called from custom function.
   */
  onStepButtonClick: (stepIndex: number, buttonIndex?: number, isCustom?: boolean) => void
  /**
   * Initial active step index for uncontrolled mode.
   * @default 0
   */
  initialStep?: number
}

export const Stepper = ({steps, activeStepIndex, onStepChange, onStepButtonClick, initialStep = 0}: StepperProps) => {
  const isControlled = activeStepIndex !== undefined
  const [internalActiveIndex, setInternalActiveIndex] = useState<number>(initialStep)
  const currentActive = isControlled ? activeStepIndex : internalActiveIndex

  const handleStepClick = (index: number) => {
    if (index === currentActive) return
    if (isControlled) {
      onStepChange?.(index)
    } else {
      setInternalActiveIndex(index)
    }
  }

  return (
    <ol className={styles.stepper}>
      {steps.map((step, index) => {
        const isActive = index === currentActive
        const stepId = `step-${index}`
        const panelId = `panel-${index}`

        const renderDescription = () => {
          if (!step.description) return null
          let content: React.ReactNode
          if (typeof step.description === 'function') {
            content = step.description({
              onComplete: () => {
                onStepButtonClick(index, undefined, true)
              },
            })
          } else {
            content = step.description
          }
          return <div className={styles.description}>{content}</div>
        }

        const renderCustomCta = () =>
          step.customCta &&
          step.customCta({
            onComplete: () => {
              onStepButtonClick(index, undefined, true)
            },
            index,
            isActive,
          })

        const renderMultipleCtaButtons = () =>
          step.multipleCtaButtons && (
            <Stack direction="horizontal" gap="condensed" wrap="wrap">
              {step.multipleCtaButtons.map((button, btnIndex) => (
                <LinkButton
                  key={button.ctaLabel}
                  href={button.href}
                  variant={btnIndex === 0 ? 'primary' : 'default'}
                  className={styles.cta}
                  tabIndex={isActive ? 0 : -1}
                  onClick={e => {
                    e.preventDefault()
                    onStepButtonClick(index, btnIndex)
                  }}
                  data-testid={`stepper-cta-${index}-button-${btnIndex}`}
                >
                  {button.ctaLabel}
                </LinkButton>
              ))}
            </Stack>
          )

        const renderCtaButton = () =>
          step.ctaLabel && (
            <LinkButton
              href={step.href}
              variant="primary"
              className={styles.cta}
              tabIndex={isActive ? 0 : -1}
              onClick={e => {
                e.preventDefault()
                onStepButtonClick(index)
              }}
              data-testid={`stepper-cta-${index}`}
            >
              {step.ctaLabel}
            </LinkButton>
          )

        return (
          <li key={stepId} className={`${styles.step} ${isActive ? styles.active : ''}`}>
            <button
              className={styles.header}
              onClick={() => handleStepClick(index)}
              aria-expanded={isActive}
              aria-controls={panelId}
              id={stepId}
              data-testid={`stepper-button-${index}`}
            >
              <span className={styles.stepIndex} aria-hidden="true">
                {step.isComplete ? (
                  <CheckCircleFillIcon
                    className={styles.checkIcon}
                    size={16}
                    data-testid={`stepper-${stepId}-checked`}
                  />
                ) : (
                  <CircleIcon className={styles.circleIcon} size={16} data-testid={`stepper-${stepId}-unchecked`} />
                )}
              </span>
              <Heading as="h3" className={styles.stepTitle}>
                {step.title}
              </Heading>
            </button>

            <div
              id={panelId}
              role="region"
              aria-labelledby={stepId}
              aria-hidden={!isActive}
              className={`${styles.panel} ${isActive ? styles.open : ''}`}
              data-testid={`stepper-panel-${index}`}
            >
              {step.customContent ? (
                step.customContent
              ) : (
                <>
                  {renderDescription()}
                  {renderCustomCta() || renderMultipleCtaButtons() || renderCtaButton()}
                </>
              )}
            </div>
          </li>
        )
      })}
    </ol>
  )
}

try{ Stepper.displayName ||= 'Stepper' } catch {}